349	        let evidence = with(vec![inherited("tone"), inherited("size")], Some(reading(&["size"])));
350	        let shown = decide(&evidence);
351	        assert_eq!(shown.collapsed, ["tone"]);
352	        assert_eq!(shown.rows, ["size"]);
