356	/// Replaces `entry`'s props and `composes` with the checker's, keeping a description or tags only the structural pass
357	/// has, for the whole-project merge. Facts are read as [`merge_semantic_props`] reads them, from `syntax` and as
358	/// `resolver` allows. The checker's props are laid out in the layers `cx` decides ([`layer_checker_props`]).
359	#[allow(clippy::too_many_arguments)]
360	fn apply_props(
361	    entry: &mut ComponentEntry,
362	    semantic: &SemanticComponent,
363	    shared: &mut FxHashMap<u64, Vec<Arc<ParsedProp>>>,
364	    memo: &mut MergeMemo,
365	    syntax: &SourceSyntax,
366	    resolver: ResolverFacts,
367	    cx: CollapseContext,
368	) -> MergedProps {
369	    // The whole-project merge replaces the props and leaves `@types/react`'s to the inheritance layers. A component
370	    // with no layer has nowhere to leave them: a context's `Provider` (`value`, `children`) or a `th`/`td` attribute
371	    // intersection names no element. Its `@types/react` props the structural pass lists stay, as the curated mode
372	    // keeps them (`targets_of` asks the checker for those names only, `key` among them only if the component lists it).
373	    let layered = !entry.inheritance.is_empty();
